package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        java.time.LocalDate effective = owner.getRegistrationDate() == null
            ? java.time.LocalDate.now() : owner.getRegistrationDate();
        owner.setRegistrationDate(BusinessDay.roll(effective));
        built.set(owner);
    }
}
===== RequireDailyCapacity =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DailyLimitException;

/**
 * Rejects a create-owner request once {@value #DAILY_LIMIT} or more owners have already been
 * registered today, before {@link BuildOwner} runs. Owners are counted by registrationDate,
 * which {@link BuildOwner} defaults to today for newly created owners.
 */
public class RequireDailyCapacity {

    static final int DAILY_LIMIT = 100;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DailyLimitException {
        LocalDate day = BusinessDay.roll(
            request.getRegistrationDate() == null ? LocalDate.now() : request.getRegistrationDate());
        long count = ownerRepository.findAll().stream()
            .filter(existing -> day.equals(existing.getRegistrationDate()))
            .count();
        if (count >= DAILY_LIMIT) {
            throw new DailyLimitException(count);
        }
    }
}
===== BulkSignup =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a bulk signup: {@code true} once more than {@value #THRESHOLD} owners have already
 * been created today, otherwise {@code false}. Owners are counted by registrationDate on the
 * current business day, matching how {@link BuildOwner} dates newly created owners and how
 * {@link RequireDailyCapacity} enforces the daily cap.
 */
public final class BulkSignup {

    static final int THRESHOLD = 80;

    private BulkSignup() {
    }

    public static boolean warningToday(OwnerRepository ownerRepository) {
        LocalDate today = BusinessDay.roll(LocalDate.now());
        long count = ownerRepository.findAll().stream()
            .filter(existing -> today.equals(existing.getRegistrationDate()))
            .count();
        return count > THRESHOLD;
    }
}

